  2383	GfxFontDict::GfxFontDict(XRef *xref, Ref *fontDictRef, Dict *fontDict) {
  2384	  int i;
  2385	  Ref r;
  2386	
  2387	  numFonts = fontDict->getLength();
  2388	  fonts = (GfxFont **)gmallocn(numFonts, sizeof(GfxFont *));
  2389	  for (i = 0; i < numFonts; ++i) {
  2390	    const Object &obj1 = fontDict->getValNF(i);
  2391	    Object obj2 = obj1.fetch(xref);
  2392	    if (obj2.isDict()) {
  2393	      if (obj1.isRef()) {
  2394	        r = obj1.getRef();
  2395	      } else if (fontDictRef) {
  2396	        // legal generation numbers are five digits, so we use a
  2397	        // 6-digit number here
  2398	        r.gen = 100000 + fontDictRef->num;
  2399	        r.num = i;
  2400	      } else {
  2401	        // no indirect reference for this font, or for the containing
  2402	        // font dict, so hash the font and use that
  2403	        r.gen = 100000;
  2404	        r.num = hashFontObject(&obj2);
  2405	      }
  2406	      fonts[i] = GfxFont::makeFont(xref, fontDict->getKey(i),
  2407	                                   r, obj2.getDict());
  2408	      if (fonts[i] && !fonts[i]->isOk()) {
  2409	        // XXX: it may be meaningful to distinguish between
  2410	        // NULL and !isOk() so that when we do lookups
  2411	        // we can tell the difference between a missing font
  2412	        // and a font that is just !isOk()
  2413	        fonts[i]->decRefCnt();
  2414	        fonts[i] = nullptr;
  2415	      }
  2416	    } else {
  2417	      error(errSyntaxError, -1, "font resource is not a dictionary");
  2418	      fonts[i] = nullptr;
  2419	    }
  2420	  }
  2421	}
